-- A range selects a list: @1:2 the first two, @2: from the second to the end, @:2 up to the second.
-- Both ends are included. The slice of a fixed-size array is a list.
SELECT
  t.nr
, CASE WHEN t.tags IS NULL THEN NULL ELSE CAST(MULTISET(SELECT E.V FROM (SELECT COLUMN_VALUE V, ROWNUM RN FROM TABLE(t.tags) Z) E WHERE E.RN >= 1 AND E.RN <= 2 ORDER BY E.RN) AS SYS.ODCIVARCHAR2LIST) END AS first_two
, CASE WHEN t.tags IS NULL THEN NULL ELSE CAST(MULTISET(SELECT E.V FROM (SELECT COLUMN_VALUE V, ROWNUM RN FROM TABLE(t.tags) Z) E WHERE E.RN >= 2 ORDER BY E.RN) AS SYS.ODCIVARCHAR2LIST) END AS from_second
, CASE WHEN t.tags IS NULL THEN NULL ELSE CAST(MULTISET(SELECT E.V FROM (SELECT COLUMN_VALUE V, ROWNUM RN FROM TABLE(t.tags) Z) E WHERE E.RN <= 2 ORDER BY E.RN) AS SYS.ODCIVARCHAR2LIST) END AS up_to_second
, CASE WHEN t.vec IS NULL THEN NULL ELSE CAST(MULTISET(SELECT E.V FROM (SELECT COLUMN_VALUE V, ROWNUM RN FROM TABLE(t.vec) Z) E WHERE E.RN >= 1 AND E.RN <= 2 ORDER BY E.RN) AS SYS.ODCINUMBERLIST) END AS vec_head
FROM
 check_complex t